#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_black;
float4 amzSample_black(float2 uv) { return float4(amzt_black.eval((float2(uv.x,1.0-uv.y)*float2(1920.0,1080.0)))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_black(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_blendMode;
uniform float2 amzp_position;
uniform float amzp_progress;
uniform float amzp_orientX;
uniform float amzp_orientY;
uniform float amzp_scale;
uniform float amzp_bright;
uniform float amzp_alpha;
uniform float amzp_AMOUNT;
uniform float amzp_SPARKS;
uniform float amzp_onecolor;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
    float n21(float2 n) {
        return fract(sin(dot(n, float2(12.9898, 4.1414))) * 43758.5453);
    }
    float2 randomSpark(float noise) {
        float2 v0 = float2((noise - .5) * 13., (fract(noise * 123.) - .5) * 15.);
        return v0;
    }
    float2 circularSpark(float i, float noiseId, float noiseSpark) {
        noiseId = fract(noiseId * 7897654.45);
        float a = (6.28 / amzp_SPARKS) * i;
        float speed = 10.*clamp(noiseId, .7, 1.);
        float x = sin(a + amzp_orientX*((noiseId-.5)*3.));
        float y = cos(a + amzp_orientY*(fract(noiseId*4567.332) - .5)*2.);
        float2 v0 = float2(x, y) * speed;
        return v0;
    }
    float2 rocket(float2 start, float t) {
        float y = t;
        float x = sin(y*10.+cos(t*3.))*.1;
        float2 p = start + float2(x, y * 8.);
        return p;
    }
    float3 firework(float2 uv, float index, float pauseTime) {
        float3 col = float3(0.);
        float timeScale = 1.;
        float2 gravity = float2(0., -9.8);
        float explodeTime = .9;
        float rocketTime = 1.1;
        float episodeTime = rocketTime + explodeTime + pauseTime;
        float ratio = screen.zw.x / screen.zw.y;
        float timeScaled = (amzp_progress - pauseTime) / timeScale;
        float id = floor(timeScaled / episodeTime);
        float et = mod(timeScaled, episodeTime);
        float noiseId = n21(float2(id+1., index+1.));
        float amzp_scale = clamp(fract(noiseId*567.53)*30., 10., 30.);
        uv *= amzp_scale;
        rocketTime -= (fract(noiseId*1234.543) * .5);
        float2 pRocket = rocket(float2(0. + ((noiseId - .5)*amzp_scale*ratio), 0. - amzp_scale/2.), clamp(et, 0., rocketTime));
        if (et < rocketTime) {
            float rd = length(uv - pRocket);
            col += pow(.05/rd , 1.9) * float3(0.9, .3, .0);
        }
        if (et > rocketTime && et < (rocketTime + explodeTime)) {
            float burst = sign(fract(noiseId*44432.22) - .6);
            for(int i = 0 ; i < int(amzp_SPARKS) ; i++) {
                    float2 center = pRocket;
                    float fi = float(i);
                    float noiseSpark = fract(n21(float2(id*10.+index*20., float(i+1))) * 332.44);
                    float t = et - rocketTime;
                    float2 v0;
                    if (fract(noiseId*3532.33) > .5) {
                        v0 = randomSpark(noiseSpark);
                        t -= noiseSpark * (fract(noiseId*543.) * .2);
                    } else {
                        v0 = circularSpark(fi, noiseId, noiseSpark);
                        if ( (fract(noiseId*973.22) - .5) > 0.) {
                            float re = mod(fi, 4. + 10. * noiseId);
                            t -= floor(re/2.) * burst * .1;
                        } else {
                            t -= mod(fi, 2.) == 0. ? 0. : burst * .5*clamp(noiseId, .3, 1.);
                        }
                    }
                    float2 s = v0*t + (gravity * t * t) / 2.;
                    float2 p = center + s;
                    float d = length(uv - p);
                    if (t > 0.) {
                        float fade = clamp((1. - t/explodeTime), 0., 1.);
                        float3 sparkColor = float3(noiseId*.9, .5*fract(noiseId *456.33), .5*fract(noiseId *1456.33));
                        float3 c = (.05 / d) * sparkColor;
                        col += c * fade;
                    }
                }
        }
        return col;
    }
    void amzRender()
    {
        float4 texColorX = amzTexture(1,amzScreenNorm());
        float4 texColor = amzTexture(0,amzScreenNorm());
     float4 result;
     float2 uv = amzScreenNorm();
     uv /= amzp_scale;
        uv += amzp_position*float2(-1.,1.)/500.;
        uv -= 0.5;
        uv.x *= screen.zw.x / screen.zw.y;
        float3 col = float3(0.);
        for (float i = 0. ; i < amzp_AMOUNT ; i += 1.) {
            col += firework(uv, i + 1., (i * (amzp_AMOUNT/60.0)));
        }
        result = float4(col, 1.);
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 gradmap;
            float luminance = dot(result.rgb, luminanceWeighting);
            gradmap = mix(amzp_color1,amzp_color2,luminance)*result.a;
        float4 factor;
        if ( (amzp_onecolor>0.5) ) { factor = mix(texColorX,gradmap,amzp_alpha); }
     else { factor = mix(texColorX,result,amzp_alpha); }
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor,resultfinal, amzp_alpha) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

